samples=[(a1,5,7),(a2,4,6)]
master={}; conflicts=[]
for grid,hr,vc in samples:
 for r,row in enumerate(grid):
  for c,v in enumerate(row):
   if r==hr or c==vc: continue
   k=(abs(r-hr),abs(c-vc))
   if k in master and master[k]!=v: conflicts.append((k,master[k],v,(r,c)))
   master[k]=v
print('master keys',len(master),'conflicts',len(conflicts),conflicts[:20])
